'use client';

import { EventCalendar, useEventList } from './_parts';
import { buildSampleEvents } from './_parts/sample-events';

export default function EventCalendar06() {
  const { events, addEvent, updateEvent, deleteEvent } =
    useEventList(buildSampleEvents);

  return (
    <EventCalendar
      views={['agenda']}
      events={events}
      onEventAdd={addEvent}
      onEventUpdate={updateEvent}
      onEventDelete={deleteEvent}
    />
  );
}

'use client';

import { addDays, format, isSameMonth, isToday } from 'date-fns';
import { useMemo } from 'react';

import { CalendarIcon } from '@/registry/ndeko/lib/icons';

import { AgendaDaysToShow } from './constants';
import { EventListRow } from './event-list-row';
import { dayKeyOf } from './navigation';
import type { CalendarEvent } from './types';
import { getAgendaEventsForDay } from './utils';

type AgendaViewProps = {
  currentDate: Date;
  events: CalendarEvent[];
  onEventSelect: (event: CalendarEvent) => void;
};

type AgendaDay = {
  day: Date;
  events: CalendarEvent[];
};

function AgendaEmptyState() {
  return (
    <div className='flex flex-col items-center justify-center gap-1 px-4 py-20 text-center'>
      <span className='keycap-3d text-muted-foreground mb-2 flex size-10 items-center justify-center rounded-lg'>
        <CalendarIcon className='size-5' />
      </span>
      <h3 className='text-sm font-medium'>
        No events in these {AgendaDaysToShow} days
      </h3>
      <p className='text-muted-foreground text-[13px]'>
        Pick New event to plan one.
      </p>
    </div>
  );
}

function agendaDayLabelOf(day: Date) {
  const date = format(day, 'EEEE, MMMM d');
  if (isToday(day)) {
    return `Today, ${date}`;
  }
  return date;
}

function showsMonthOf(agendaDays: AgendaDay[], index: number) {
  if (index === 0) {
    return true;
  }
  const previousDay = agendaDays[index - 1].day;
  return !isSameMonth(previousDay, agendaDays[index].day);
}

type AgendaDateProps = {
  day: Date;
  showsMonth: boolean;
};

function AgendaDate({ day, showsMonth }: AgendaDateProps) {
  const isTodayDay = isToday(day);

  return (
    <div
      aria-hidden='true'
      className='group/date flex flex-col items-center pt-1.5 leading-none'
      data-today={isTodayDay || undefined}
    >
      <span className='text-muted-foreground group-data-today/date:text-primary-ink text-xs'>
        {format(day, 'EEE')}
      </span>
      <span className='group-data-today/date:text-primary-ink mt-1 text-lg font-semibold tabular-nums'>
        {format(day, 'd')}
      </span>
      {showsMonth && (
        <span className='text-muted-foreground mt-1 text-[11px]'>
          {format(day, 'MMM')}
        </span>
      )}
    </div>
  );
}

export function AgendaView({
  currentDate,
  events,
  onEventSelect,
}: AgendaViewProps) {
  const agendaDays = useMemo(() => {
    const days = Array.from({ length: AgendaDaysToShow }, (_, index) =>
      addDays(currentDate, index)
    );
    const withEvents = days.map((day) => ({
      day,
      events: getAgendaEventsForDay(events, day),
    }));
    return withEvents.filter((agendaDay) => agendaDay.events.length > 0);
  }, [currentDate, events]);
  const hasEvents = agendaDays.length > 0;

  return (
    <div
      data-slot='agenda-view'
      className='hairline-t border-border max-h-(--calendar-scroll-height) min-h-0 flex-1 overflow-y-auto'
    >
      {!hasEvents && <AgendaEmptyState />}
      {hasEvents && (
        <ol className='flex flex-col gap-4 p-2 @2xl:p-3'>
          {agendaDays.map((agendaDay, index) => (
            <li
              key={dayKeyOf(agendaDay.day)}
              className='grid grid-cols-[3rem_minmax(0,1fr)] gap-1 @2xl:grid-cols-[3.5rem_minmax(0,1fr)] @2xl:gap-2'
            >
              <AgendaDate
                day={agendaDay.day}
                showsMonth={showsMonthOf(agendaDays, index)}
              />
              <ul
                className='flex flex-col'
                aria-label={agendaDayLabelOf(agendaDay.day)}
              >
                {agendaDay.events.map((event) => (
                  <li key={event.id}>
                    <EventListRow
                      event={event}
                      day={agendaDay.day}
                      onClick={() => onEventSelect(event)}
                    />
                  </li>
                ))}
              </ul>
            </li>
          ))}
        </ol>
      )}
    </div>
  );
}

'use client';

import {
  DndContext,
  DragOverlay,
  MouseSensor,
  PointerSensor,
  TouchSensor,
  useSensor,
  useSensors,
  type DragEndEvent,
  type DragOverEvent,
  type DragStartEvent,
  type UniqueIdentifier,
} from '@dnd-kit/core';
import {
  addMinutes,
  differenceInMinutes,
  isSameDay,
  isSameMinute,
} from 'date-fns';
import { motion, type Transition } from 'motion/react';
import { createContext, useContext, useId, useState } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';

import { EventItem } from './event-item';
import type { CalendarEvent, TimedView } from './types';

export const DROP_SPRING: Transition = {
  type: 'spring',
  bounce: 0,
  duration: 0.35,
};

type DragState = {
  activeEvent: CalendarEvent | null;
  activeId: UniqueIdentifier | null;
  activeView: TimedView | null;
  currentTime: Date | null;
  eventHeight: number | null;
};

type CalendarDndContextValue = DragState & {
  droppedEventId: string | null;
  clearDroppedEvent: () => void;
};

type ActiveData = {
  event: CalendarEvent;
  view: TimedView;
  height?: number | null;
};

type OverData = { date: Date; time?: number };

const IDLE_DRAG: DragState = {
  activeEvent: null,
  activeId: null,
  activeView: null,
  currentTime: null,
  eventHeight: null,
};

const CalendarDndContext = createContext<CalendarDndContextValue>({
  ...IDLE_DRAG,
  droppedEventId: null,
  clearDroppedEvent: () => undefined,
});

export function useCalendarDnd() {
  return useContext(CalendarDndContext);
}

/** The minutes of a slot, rounded to the closest quarter hour. */
function quarterMinutesOf(fractionalHour: number) {
  if (fractionalHour < 0.125) {
    return 0;
  }
  if (fractionalHour < 0.375) {
    return 15;
  }
  if (fractionalHour < 0.625) {
    return 30;
  }
  return 45;
}

function slotTimeOf(date: Date, time: number) {
  const slotTime = new Date(date);
  const hours = Math.floor(time);
  const minutes = quarterMinutesOf(time - hours);
  slotTime.setHours(hours, minutes, 0, 0);
  return slotTime;
}

function sameTimeOnDay(date: Date, time: Date) {
  const moved = new Date(date);
  moved.setHours(
    time.getHours(),
    time.getMinutes(),
    time.getSeconds(),
    time.getMilliseconds()
  );
  return moved;
}

function overlayHeightOf(eventHeight: number | null) {
  if (eventHeight) {
    return `${eventHeight}px`;
  }
  return 'auto';
}

function overlayLayoutIdOf(
  event: CalendarEvent,
  shouldReduceMotion: boolean | null
) {
  if (shouldReduceMotion) {
    return undefined;
  }
  return `dropped-event-${event.id}`;
}

function DragPreview({ drag }: { drag: DragState }) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const { activeEvent, activeView } = drag;
  if (!activeEvent || !activeView) {
    return null;
  }

  return (
    <motion.div
      layoutId={overlayLayoutIdOf(activeEvent, shouldReduceMotion)}
      transition={DROP_SPRING}
      style={{ height: overlayHeightOf(drag.eventHeight) }}
    >
      <EventItem
        event={activeEvent}
        view={activeView}
        isDragging
        showTime={activeView !== 'month'}
        currentTime={drag.currentTime ?? undefined}
      />
    </motion.div>
  );
}

type CalendarDndProviderProps = {
  children: React.ReactNode;
  onEventUpdate: (event: CalendarEvent) => void;
};

export function CalendarDndProvider({
  children,
  onEventUpdate,
}: CalendarDndProviderProps) {
  const [drag, setDrag] = useState<DragState>(IDLE_DRAG);
  const [droppedEventId, setDroppedEventId] = useState<string | null>(null);
  const dndContextId = useId();

  const sensors = useSensors(
    useSensor(MouseSensor, { activationConstraint: { distance: 5 } }),
    useSensor(TouchSensor, {
      activationConstraint: { delay: 250, tolerance: 5 },
    }),
    useSensor(PointerSensor, { activationConstraint: { distance: 5 } })
  );

  function clearDroppedEvent() {
    setDroppedEventId(null);
  }

  function handleDragStart({ active }: DragStartEvent) {
    const data = active.data.current as ActiveData | undefined;
    if (!data) {
      return;
    }
    setDrag({
      activeEvent: data.event,
      activeId: active.id,
      activeView: data.view,
      currentTime: new Date(data.event.start),
      eventHeight: data.height ?? null,
    });
  }

  function handleDragOver({ over }: DragOverEvent) {
    const overData = over?.data.current as OverData | undefined;
    if (!overData) {
      return;
    }
    if (!drag.activeEvent) {
      return;
    }
    const isTimeSlot = overData.time !== undefined;
    const isTimeGrid = drag.activeView !== 'month';
    const currentTime = drag.currentTime;

    if (isTimeSlot && isTimeGrid) {
      const slotTime = slotTimeOf(overData.date, overData.time ?? 0);
      const hasMoved = !currentTime || !isSameMinute(slotTime, currentTime);
      if (hasMoved) {
        setDrag((state) => ({ ...state, currentTime: slotTime }));
      }
      return;
    }

    if (drag.activeView !== 'month') {
      return;
    }
    let dayTime = new Date(overData.date);
    if (currentTime) {
      dayTime = sameTimeOnDay(overData.date, currentTime);
    }
    const hasChangedDay = !currentTime || !isSameDay(dayTime, currentTime);
    if (hasChangedDay) {
      setDrag((state) => ({ ...state, currentTime: dayTime }));
    }
  }

  function moveEvent(
    over: NonNullable<DragEndEvent['over']>,
    currentTime: Date
  ) {
    const activeEvent = drag.activeEvent;
    const overData = over.data.current as OverData | undefined;
    if (!activeEvent) {
      return;
    }
    if (!overData?.date) {
      return;
    }

    let newStart = sameTimeOnDay(overData.date, currentTime);
    if (overData.time !== undefined) {
      newStart = slotTimeOf(overData.date, overData.time);
    }
    const originalStart = new Date(activeEvent.start);
    const originalEnd = new Date(activeEvent.end);
    const durationMinutes = differenceInMinutes(originalEnd, originalStart);
    const newEnd = addMinutes(newStart, durationMinutes);
    const hasStartTimeChanged = !isSameMinute(originalStart, newStart);

    if (hasStartTimeChanged) {
      onEventUpdate({ ...activeEvent, start: newStart, end: newEnd });
      setDroppedEventId(activeEvent.id);
    }
  }

  function handleDragEnd({ over }: DragEndEvent) {
    const currentTime = drag.currentTime;
    setDrag(IDLE_DRAG);
    if (!over) {
      return;
    }
    if (!currentTime) {
      return;
    }
    moveEvent(over, currentTime);
  }

  const contextValue: CalendarDndContextValue = {
    ...drag,
    droppedEventId,
    clearDroppedEvent,
  };

  return (
    <DndContext
      id={dndContextId}
      sensors={sensors}
      onDragStart={handleDragStart}
      onDragOver={handleDragOver}
      onDragEnd={handleDragEnd}
      onDragCancel={() => setDrag(IDLE_DRAG)}
    >
      <CalendarDndContext.Provider value={contextValue}>
        {children}

        <DragOverlay adjustScale={false} dropAnimation={null}>
          <DragPreview drag={drag} />
        </DragOverlay>
      </CalendarDndContext.Provider>
    </DndContext>
  );
}

'use client';

import {
  AnimatePresence,
  motion,
  type Transition,
  type Variants,
} from 'motion/react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { ChevronLeftIcon, ChevronRightIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { Button } from '@/registry/ndeko/ui/button';

import {
  periodCaptionOf,
  periodKeyOf,
  periodTitleOf,
  periodUnitOf,
} from './navigation';
import type { CalendarView } from './types';

const TITLE_SHIFT_PX = 6;

const TITLE_TRANSITION: Transition = {
  duration: 0.2,
  ease: [0.23, 1, 0.32, 1],
};

const TITLE_EXIT: Transition = { duration: 0.1, ease: [0.23, 1, 0.32, 1] };

const TITLE_VARIANTS: Variants = {
  enter: (direction: number) => {
    const offset = direction * TITLE_SHIFT_PX;
    return { opacity: 0, x: offset };
  },
  visible: { opacity: 1, x: 0 },
  exit: (direction: number) => {
    const offset = direction * TITLE_SHIFT_PX;
    return { opacity: 0, x: -offset, transition: TITLE_EXIT };
  },
};

const FADE_VARIANTS: Variants = {
  enter: { opacity: 0 },
  visible: { opacity: 1 },
  exit: { opacity: 0, transition: TITLE_EXIT },
};

function titleVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return TITLE_VARIANTS;
}

type PeriodHeadingProps = {
  view: CalendarView;
  date: Date;
  direction: number;
};

/** The period on screen. Only the heading answers previous and next, with a short nudge. */
function PeriodHeading({ view, date, direction }: PeriodHeadingProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const title = periodTitleOf(date, view);
  const caption = periodCaptionOf(date, view);
  const titleKey = `${view}-${periodKeyOf(date, view)}`;

  return (
    <div className='flex min-w-0 flex-1 items-baseline gap-2'>
      <h2 className='relative flex min-w-0 text-sm font-semibold @2xl:text-base'>
        <span className='sr-only' aria-live='polite'>
          {title.full}
        </span>
        <AnimatePresence mode='popLayout' initial={false} custom={direction}>
          <motion.span
            key={titleKey}
            aria-hidden='true'
            className='min-w-0 truncate'
            custom={direction}
            variants={titleVariantsOf(shouldReduceMotion)}
            initial='enter'
            animate='visible'
            exit='exit'
            transition={TITLE_TRANSITION}
          >
            <span className='@xl:hidden'>{title.short}</span>
            <span className='hidden @xl:inline'>{title.full}</span>
          </motion.span>
        </AnimatePresence>
      </h2>
      {caption && (
        <span className='text-muted-foreground hidden shrink-0 text-xs @3xl:inline'>
          {caption}
        </span>
      )}
    </div>
  );
}

type CalendarHeaderProps = {
  view: CalendarView;
  date: Date;
  /** `1` after next, `-1` after previous, `0` when the view changes. */
  direction: number;
  onPrevious: () => void;
  onNext: () => void;
  onToday: () => void;
  /** Placed before Today, for example a button that opens a sidebar. */
  start?: React.ReactNode;
  /** Placed after the heading: the view switcher and the actions. */
  children?: React.ReactNode;
  className?: string;
};

/**
 * Today, previous and next, and the period heading. On a narrow calendar the children wrap
 * under it; a child with `order-last w-full` takes the second row on its own.
 */
export function CalendarHeader({
  view,
  date,
  direction,
  onPrevious,
  onNext,
  onToday,
  start,
  children,
  className,
}: CalendarHeaderProps) {
  const unit = periodUnitOf(view);

  return (
    <div
      className={cn(
        'flex flex-wrap items-center gap-2 p-3 @2xl:flex-nowrap @2xl:gap-3 @2xl:px-4',
        className
      )}
    >
      {start}
      <Button variant='outline' onClick={onToday}>
        Today
      </Button>
      <div className='flex items-center'>
        <Button
          variant='ghost'
          size='icon'
          aria-label={`Previous ${unit}`}
          onClick={onPrevious}
        >
          <ChevronLeftIcon />
        </Button>
        <Button
          variant='ghost'
          size='icon'
          aria-label={`Next ${unit}`}
          onClick={onNext}
        >
          <ChevronRightIcon />
        </Button>
      </div>
      <PeriodHeading view={view} date={date} direction={direction} />
      {children}
    </div>
  );
}

import type { CalendarView, EventColor, EventColorOption } from './types';

export const EventHeight = 24;

export const EventGap = 4;

export const WeekCellsHeight = 64;

export const AgendaDaysToShow = 30;

export const StartHour = 0;
export const EndHour = 24;

export const DefaultStartHour = 9;
export const DefaultEndHour = 10;

/** The hour the week and day grids open on, so the morning shows without scrolling. */
export const ScrollToHour = 7;

export const WeekStartsOn = 0;

/** Height of the scrolling time grid and agenda when the calendar sizes itself to its content. */
export const ScrollAreaHeight = '34rem';

export const DefaultEventColor: EventColor = 'info';

export const EventColors: EventColorOption[] = [
  { value: 'info', label: 'Blue' },
  { value: 'primary', label: 'Indigo' },
  { value: 'success', label: 'Green' },
  { value: 'warning', label: 'Amber' },
  { value: 'destructive', label: 'Red' },
];

export type ViewOption = {
  view: CalendarView;
  label: string;
  shortcut: string;
};

export const ViewOptions: ViewOption[] = [
  { view: 'day', label: 'Day', shortcut: 'D' },
  { view: 'week', label: 'Week', shortcut: 'W' },
  { view: 'month', label: 'Month', shortcut: 'M' },
  { view: 'year', label: 'Year', shortcut: 'Y' },
  { view: 'agenda', label: 'Agenda', shortcut: 'A' },
];

export const AllViews: CalendarView[] = ViewOptions.map(
  (option) => option.view
);

'use client';

import { format, isToday } from 'date-fns';

import { PlusIcon } from '@/registry/ndeko/lib/icons';
import { cn } from '@/registry/ndeko/lib/utils';
import { AnimatedSize } from '@/registry/ndeko/ui/animated-size';
import { Button } from '@/registry/ndeko/ui/button';

import { EventListRow } from './event-list-row';
import type { CalendarEvent } from './types';
import {
  defaultStartOf,
  eventCountLabelOf,
  getAgendaEventsForDay,
} from './utils';

type DayEventsPanelProps = {
  day: Date;
  events: CalendarEvent[];
  onEventSelect: (event: CalendarEvent) => void;
  /** Offers to plan an event when the day is empty. */
  onEventCreate?: (startTime: Date) => void;
  className?: string;
};

type EmptyDayProps = {
  day: Date;
  onEventCreate?: (startTime: Date) => void;
};

function EmptyDay({ day, onEventCreate }: EmptyDayProps) {
  const canCreate = Boolean(onEventCreate);

  function createEvent() {
    const start = defaultStartOf(day);
    onEventCreate?.(start);
  }

  return (
    <div className='hairline-border border-border flex flex-wrap items-center justify-between gap-3 rounded-lg border-dashed px-3 py-3'>
      <p className='text-muted-foreground text-[13px]'>No events on this day</p>
      {canCreate && (
        <Button variant='outline' size='sm' onClick={createEvent}>
          <PlusIcon />
          New event
        </Button>
      )}
    </div>
  );
}

/** The events of one day as a list, with a heading that names the day and counts them. */
export function DayEventsPanel({
  day,
  events,
  onEventSelect,
  onEventCreate,
  className,
}: DayEventsPanelProps) {
  const dayEvents = getAgendaEventsForDay(events, day);
  const hasEvents = dayEvents.length > 0;
  const isTodayDay = isToday(day);

  return (
    <section
      aria-label={format(day, 'EEEE, MMMM d')}
      className={cn('flex min-w-0 flex-col gap-2', className)}
    >
      <header
        aria-live='polite'
        className='flex items-baseline justify-between gap-3 px-2'
      >
        <h3 className='flex min-w-0 items-baseline gap-2 text-sm font-medium'>
          <span className='truncate'>{format(day, 'EEEE, MMMM d')}</span>
          {isTodayDay && (
            <span className='text-primary-ink shrink-0 text-xs font-normal'>
              Today
            </span>
          )}
        </h3>
        <p className='text-muted-foreground shrink-0 text-xs tabular-nums'>
          {eventCountLabelOf(dayEvents.length)}
        </p>
      </header>
      <AnimatedSize>
        {hasEvents && (
          <ul className='flex flex-col'>
            {dayEvents.map((event) => (
              <li key={event.id}>
                <EventListRow
                  event={event}
                  day={day}
                  onClick={() => onEventSelect(event)}
                />
              </li>
            ))}
          </ul>
        )}
        {!hasEvents && <EmptyDay day={day} onEventCreate={onEventCreate} />}
      </AnimatedSize>
    </section>
  );
}

'use client';

import { format, isSameDay } from 'date-fns';
import { useMemo } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';

import { EventItem } from './event-item';
import {
  CurrentTimeLine,
  HourLabels,
  hoursOfDay,
  PositionedEvents,
  QuarterSlots,
  TimeGridScroller,
} from './time-grid';
import type { CalendarEvent } from './types';
import { useCurrentTimeIndicator } from './use-current-time-indicator';
import { isMultiDayEvent, occursOnDay, positionTimedEvents } from './utils';

const DAY_COLUMNS = 'grid grid-cols-[3.5rem_minmax(0,1fr)]';

type DayViewProps = {
  currentDate: Date;
  events: CalendarEvent[];
  onEventSelect: (event: CalendarEvent) => void;
  onEventCreate: (startTime: Date) => void;
};

export function DayView({
  currentDate,
  events,
  onEventSelect,
  onEventCreate,
}: DayViewProps) {
  const hours = useMemo(() => hoursOfDay(currentDate), [currentDate]);

  const dayEvents = useMemo(
    () => events.filter((event) => occursOnDay(event, currentDate)),
    [currentDate, events]
  );

  const allDayEvents = useMemo(
    () => dayEvents.filter(isMultiDayEvent),
    [dayEvents]
  );

  const positionedEvents = useMemo(() => {
    const timedEvents = dayEvents.filter((event) => !isMultiDayEvent(event));
    return positionTimedEvents(timedEvents, currentDate);
  }, [currentDate, dayEvents]);

  const { currentTimePosition, currentTimeVisible } = useCurrentTimeIndicator(
    currentDate,
    'day'
  );
  const showAllDaySection = allDayEvents.length > 0;

  function handleEventClick(
    event: CalendarEvent,
    clickEvent: React.MouseEvent
  ) {
    clickEvent.stopPropagation();
    onEventSelect(event);
  }

  return (
    <div
      data-slot='day-view'
      className='hairline-t border-border flex min-h-0 flex-1 flex-col'
    >
      <TimeGridScroller label={format(currentDate, 'EEEE, MMMM d')}>
        {showAllDaySection && (
          <div
            className={cn(
              DAY_COLUMNS,
              'bg-card hairline-b border-border sticky top-0 z-30'
            )}
          >
            <div className='hairline-r border-border text-muted-foreground flex items-end justify-end pe-2 pb-2 text-[10px] @3xl:text-xs'>
              All day
            </div>
            <div className='relative p-1'>
              {allDayEvents.map((event) => (
                <EventItem
                  key={`spanning-${event.id}`}
                  onClick={(clickEvent) => handleEventClick(event, clickEvent)}
                  event={event}
                  view='month'
                  isFirstDay={isSameDay(currentDate, new Date(event.start))}
                  isLastDay={isSameDay(currentDate, new Date(event.end))}
                >
                  <span className='truncate' aria-hidden='true'>
                    {event.title}
                  </span>
                </EventItem>
              ))}
            </div>
          </div>
        )}

        <div className={DAY_COLUMNS}>
          <div className='hairline-r border-border'>
            <HourLabels hours={hours} />
          </div>

          <div className='relative'>
            <PositionedEvents
              positionedEvents={positionedEvents}
              view='day'
              onEventClick={handleEventClick}
            />
            {currentTimeVisible && (
              <CurrentTimeLine position={currentTimePosition} />
            )}
            <QuarterSlots
              day={currentDate}
              hours={hours}
              idPrefix='day-cell'
              onEventCreate={onEventCreate}
            />
          </div>
        </div>
      </TimeGridScroller>
    </div>
  );
}

