          ))}
        </SelectContent>
      </Select>
    </div>
  );
}

function swapVariantsOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return FADE_VARIANTS;
  }
  return SWAP_VARIANTS;
}

function SwappingLabel({ label }: { label: string }) {
  const shouldReduceMotion = usePrefersReducedMotion();

  return (
    <span className='relative inline-flex'>
      <AnimatePresence mode='popLayout' initial={false}>
        <motion.span
          key={label}
          variants={swapVariantsOf(shouldReduceMotion)}
          initial='enter'
          animate='visible'
          exit='exit'
          transition={SWAP}
        >
          {label}
        </motion.span>
      </AnimatePresence>
    </span>
  );
}

function labelOfColor(color: EventColor, options: EventColorOption[]) {
  const option = options.find((candidate) => candidate.value === color);
  return option?.label ?? '';
}

type ColorFieldProps = {
  color: EventColor;
  options: EventColorOption[];
  legend: string;
  onChange: (color: EventColor) => void;
};

function ColorField({ color, options, legend, onChange }: ColorFieldProps) {
  function pickColor(value: unknown) {
    if (isEventColor(value)) {
      onChange(value);
    }
  }

  return (
    <fieldset>
      <legend className='text-foreground mb-3 flex items-baseline gap-2 text-[13px] leading-none font-medium'>
        {legend}
        <span aria-hidden='true' className='text-muted-foreground font-normal'>
          <SwappingLabel label={labelOfColor(color, options)} />
        </span>
      </legend>
      <RadioGroup
        className='flex flex-wrap gap-1.5'
        value={color}
        onValueChange={pickColor}
      >
        {options.map((option) => (
          <RadioGroupItem
            key={option.value}
            value={option.value}
            aria-label={option.label}
            className={COLOR_SWATCH}
            style={
              {
                '--swatch': `var(--${option.value})`,
              } as React.CSSProperties
            }
          />
        ))}
      </RadioGroup>
    </fieldset>
  );
}

function startDateOf(event: CalendarEvent | null) {
  if (event) {
    return new Date(event.start);
  }
  return new Date();
}

function endDateOf(event: CalendarEvent | null) {
  if (event) {
    return new Date(event.end);
  }
  return new Date();
}

function initialTimeOf(date: Date | undefined, fallback: string) {
  if (date) {
    return formatTimeForInput(new Date(date));
  }
  return fallback;
}

function titleOf(isExisting: boolean) {
  if (isExisting) {
    return 'Edit event';
  }
  return 'New event';
}

function saveLabelOf(isExisting: boolean) {
  if (isExisting) {
    return 'Save changes';
  }
  return 'Create event';
}

function subtitleOf(event: CalendarEvent | null) {
  if (!event) {
    return 'The title, time, place and colour of the event.';
  }
  return whenLabelOf(event);
}

type EventFormProps = {
  event: CalendarEvent | null;
  colorOptions: EventColorOption[];
  colorLegend: string;
  onCancel: () => void;
  onSave: (event: CalendarEvent) => void;
  onDelete: (eventId: string) => void;
};

function EventForm({
  event,
  colorOptions,
  colorLegend,
  onCancel,
  onSave,
  onDelete,
}: EventFormProps) {
  const id = useId();
  const [title, setTitle] = useState(event?.title ?? '');
  const [description, setDescription] = useState(event?.description ?? '');
  const [startDate, setStartDate] = useState(() => startDateOf(event));
  const [endDate, setEndDate] = useState(() => endDateOf(event));
  const [startTime, setStartTime] = useState(() =>
    initialTimeOf(event?.start, DEFAULT_START_TIME)
  );
  const [endTime, setEndTime] = useState(() =>
    initialTimeOf(event?.end, DEFAULT_END_TIME)
  );
  const [allDay, setAllDay] = useState(event?.allDay ?? false);
  const [location, setLocation] = useState(event?.location ?? '');
  const [color, setColor] = useState<EventColor>(
    event?.color ?? DefaultEventColor
  );
  const [error, setError] = useState<string | null>(null);
  const isExisting = Boolean(event?.id);
  const hasTimes = !allDay;

  function pickStartDate(date: Date) {
    setStartDate(date);
    if (isBefore(endDate, date)) {
      setEndDate(date);
    }
    setError(null);
  }

  function pickEndDate(date: Date) {
    setEndDate(date);
    setError(null);
  }

  function handleSave(submitEvent: React.FormEvent<HTMLFormElement>) {
    submitEvent.preventDefault();
    const start = new Date(startDate);
    const end = new Date(endDate);

    if (allDay) {
      start.setHours(0, 0, 0, 0);
      end.setHours(23, 59, 59, 999);
    } else {
      const startParts = hoursAndMinutesOf(startTime);
      const endParts = hoursAndMinutesOf(endTime);
      const startIsOutside = isHourOutsideDay(startParts.hours);
      const endIsOutside = isHourOutsideDay(endParts.hours);
      if (startIsOutside || endIsOutside) {
        setError(`Pick times between ${StartHour}:00 and ${EndHour}:00.`);
        return;
      }
      start.setHours(startParts.hours, startParts.minutes, 0, 0);
      end.setHours(endParts.hours, endParts.minutes, 0, 0);
    }

    if (isBefore(end, start)) {
      setError('The end is before the start. Pick a later end.');
      return;
    }

    let eventTitle = title;
    if (!title.trim()) {
      eventTitle = UNTITLED;
    }

    onSave({
      id: event?.id ?? '',
      title: eventTitle,
      description,
      start,
      end,
      allDay,
      location,
      color,
    });
  }

  return (
    <form className='flex flex-col gap-4' onSubmit={handleSave} noValidate>
      <DialogHeader>
        <DialogTitle>{titleOf(isExisting)}</DialogTitle>
        <DialogDescription>{subtitleOf(event)}</DialogDescription>
      </DialogHeader>
      <AnimatePresence initial={false}>
        {error && (
          <motion.p
            key='error'
            role='alert'
            className='bg-destructive/10 text-destructive-ink rounded-md px-3 py-2 text-[13px]'
            initial={{ opacity: 0 }}
            animate={{ opacity: 1, transition: ENTER }}
            exit={{ opacity: 0, transition: EXIT }}
          >
            {error}
          </motion.p>
        )}
      </AnimatePresence>
      <div className='grid gap-4'>
        <div className='flex flex-col gap-1.5'>
          <Label htmlFor={`${id}-title`}>Title</Label>
          <Input
            id={`${id}-title`}
            value={title}
            placeholder={UNTITLED}
            onChange={(changeEvent) => setTitle(changeEvent.target.value)}
          />
        </div>

        <div className='flex gap-4'>
          <DatePickerField
            id={`${id}-start-date`}
            label='Start date'
            date={startDate}
            onPick={pickStartDate}
          />
          {hasTimes && (
            <TimeSelectField
              id={`${id}-start-time`}
              label='Start time'
              value={startTime}
              onChange={setStartTime}
            />
          )}
        </div>

        <div className='flex gap-4'>
          <DatePickerField
            id={`${id}-end-date`}
            label='End date'
            date={endDate}
            disabledBefore={startDate}
            onPick={pickEndDate}
          />
          {hasTimes && (
            <TimeSelectField
              id={`${id}-end-time`}
              label='End time'
              value={endTime}
              onChange={setEndTime}
            />
          )}
        </div>

        <div className='flex items-center gap-2'>
          <Checkbox
            id={`${id}-all-day`}
            checked={allDay}
            onCheckedChange={setAllDay}
          />
          <Label htmlFor={`${id}-all-day`}>All day</Label>
        </div>

        <div className='flex flex-col gap-1.5'>
          <Label htmlFor={`${id}-location`}>Location</Label>
          <Input
            id={`${id}-location`}
            value={location}
            onChange={(changeEvent) => setLocation(changeEvent.target.value)}
          />
        </div>

        <div className='flex flex-col gap-1.5'>
          <Label htmlFor={`${id}-description`}>Description</Label>
          <Textarea
            id={`${id}-description`}
            value={description}
            onChange={(changeEvent) => setDescription(changeEvent.target.value)}
            rows={3}
          />
        </div>

        <ColorField
          color={color}
          options={colorOptions}
          legend={colorLegend}
          onChange={setColor}
        />
      </div>
      <DialogFooter className='flex-row sm:justify-between'>
        {isExisting && (
          <Button
            type='button'
            variant='outline'
            size='icon'
            onClick={() => onDelete(event?.id ?? '')}
            aria-label='Delete event'
          >
            <TrashIcon />
          </Button>
        )}
        <div className='flex flex-1 justify-end gap-2'>
          <Button type='button' variant='outline' onClick={onCancel}>
            Cancel
          </Button>
          <Button type='submit'>{saveLabelOf(isExisting)}</Button>
        </div>
      </DialogFooter>
    </form>
  );
}

type EventDialogProps = {
  event: CalendarEvent | null;
  isOpen: boolean;
  /** Changes on every opening, so the form starts from the event it was opened for. */
  session: number;
  onClose: () => void;
  onSave: (event: CalendarEvent) => void;
  onDelete: (eventId: string) => void;
  /** The colours to pick from, with their names: plain colours, or the calendars of an app. */
  colorOptions?: EventColorOption[];
  colorLegend?: string;
};

/**
 * One layer for reading and changing an event. A click on an event opens it here, ready to
 * edit; a click on an empty slot opens it as a new event at that time.
 */
export function EventDialog({
  event,
  isOpen,
  session,
  onClose,
  onSave,
  onDelete,
  colorOptions = EventColors,
  colorLegend = 'Colour',
}: EventDialogProps) {
  function handleOpenChange(open: boolean) {
    if (!open) {
      onClose();
    }
  }

  return (
    <Dialog open={isOpen} onOpenChange={handleOpenChange}>
      <DialogContent className='sm:max-w-md'>
        <EventForm
          key={session}
          event={event}
          colorOptions={colorOptions}
          colorLegend={colorLegend}
          onCancel={onClose}
          onSave={onSave}
          onDelete={onDelete}
        />
      </DialogContent>
    </Dialog>
  );
}

'use client';

import type {
  DraggableAttributes,
  DraggableSyntheticListeners,
} from '@dnd-kit/core';
import { differenceInMinutes, isPast } from 'date-fns';

import { cn } from '@/registry/ndeko/lib/utils';

import { EventListRow } from './event-list-row';
import type { CalendarEvent, CalendarView } from './types';
import {
  clockLabelOf,
  eventChipStyle,
  getBorderRadiusClasses,
  isMultiDayEvent,
  timeRangeLabelOf,
} from './utils';

const SHORT_EVENT_MINUTES = 45;

const EVENT_SHARED = [
  'flex size-full min-w-0 cursor-pointer select-none overflow-hidden text-left outline-none',
  'transition-[opacity,background-color] duration-150 ease-(--ease-out-strong)',
  'focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-solid focus-visible:outline-ring',
  'data-dragging:cursor-grabbing data-past-event:opacity-60',
].join(' ');

/** A filled block: timed events on the hour grid and anything that spans whole days. */
const EVENT_BLOCK =
  'chip-3d px-1.5 font-medium data-dragging:drop-shadow-lg @3xl:px-2';

/** A dot and a line of text: a timed event inside a month cell, lighter than a span. */
const EVENT_DOT_ROW =
  'items-center gap-1.5 rounded-sm px-1 text-foreground hover:bg-foreground/5 data-dragging:surface-raised @3xl:px-1.5';

type EventShape = 'block' | 'dot';

function shiftedEndOf(event: CalendarEvent, currentTime: Date | undefined) {
  if (!currentTime) {
    return new Date(event.end);
  }
  const duration =
    new Date(event.end).getTime() - new Date(event.start).getTime();
  return new Date(currentTime.getTime() + duration);
}

function startOf(event: CalendarEvent, currentTime: Date | undefined) {
  if (currentTime) {
    return currentTime;
  }
  return new Date(event.start);
}

function shapeClassOf(
  shape: EventShape,
  isFirstDay: boolean,
  isLastDay: boolean
) {
  if (shape === 'dot') {
    return EVENT_DOT_ROW;
  }
  const radius = getBorderRadiusClasses(isFirstDay, isLastDay);
  return cn(EVENT_BLOCK, radius);
}

function accessibleLabelOf(event: CalendarEvent, start: Date, end: Date) {
  if (event.allDay) {
    return `${event.title}, all day`;
  }
  return `${event.title}, ${timeRangeLabelOf(start, end)}`;
}

/** Times stay visible in a popover or a drag preview, and follow the cell width elsewhere. */
function monthTimeClassOf(showTime: boolean | undefined) {
  if (showTime) {
    return '';
  }
  return 'hidden @3xl:inline';
}

function eventTimeLabelOf(event: CalendarEvent, start: Date, end: Date) {
  if (event.allDay) {
    return 'All day';
  }
  return timeRangeLabelOf(start, end);
}

type DndProps = {
  dndListeners?: DraggableSyntheticListeners;
  dndAttributes?: DraggableAttributes;
};

type EventWrapperProps = DndProps & {
  event: CalendarEvent;
  shape: EventShape;
  start: Date;
  end: Date;
  isFirstDay?: boolean;
  isLastDay?: boolean;
  isDragging?: boolean;
  tabIndex?: number;
  onClick?: (event: React.MouseEvent) => void;
  className?: string;
  children: React.ReactNode;
};

function EventWrapper({
  event,
  shape,
  start,
  end,
  isFirstDay = true,
  isLastDay = true,
  isDragging,
  tabIndex,
  onClick,
  className,
  children,
  dndListeners,
}: EventWrapperProps) {
  const isEventInPast = isPast(end);

  // Dragging is for the pointer only: the keyboard moves an event with the dialog's date and
  // time fields, so dnd-kit's keyboard drag hints are not given to assistive technology.
  return (
    <button
      type='button'
      className={cn(
        EVENT_SHARED,
        shapeClassOf(shape, isFirstDay, isLastDay),
        className
      )}
      style={eventChipStyle(event.color)}
      data-dragging={isDragging || undefined}
      data-past-event={isEventInPast || undefined}
      onClick={onClick}
      {...dndListeners}
      aria-label={accessibleLabelOf(event, start, end)}
      tabIndex={tabIndex}
    >
      {children}
    </button>
  );
}

type MonthLabelProps = {
  event: CalendarEvent;
  start: Date;
  showTime?: boolean;
};

function MonthDotLabel({ event, start, showTime }: MonthLabelProps) {
  return (
    <>
      <span
        aria-hidden='true'
        className='size-1.5 shrink-0 rounded-full bg-(--chip)'
      />
      <span
        className={cn(
          'text-muted-foreground shrink-0 tabular-nums',
          monthTimeClassOf(showTime)
        )}
      >
        {clockLabelOf(start)}
      </span>
      <span className='truncate font-medium'>{event.title}</span>
    </>
  );
}

function MonthBarLabel({ event, start, showTime }: MonthLabelProps) {
  const isTimed = !event.allDay;

  return (
    <span className='truncate'>
      {isTimed && (
        <span
          className={cn(
            'font-normal tabular-nums opacity-75',
            monthTimeClassOf(showTime)
          )}
        >
          {clockLabelOf(start)}{' '}
        </span>
      )}
      {event.title}
    </span>
  );
}

type EventItemProps = DndProps & {
  event: CalendarEvent;
  view: CalendarView;
  isDragging?: boolean;
  onClick?: (event: React.MouseEvent) => void;
  showTime?: boolean;
  currentTime?: Date;
  isFirstDay?: boolean;
  isLastDay?: boolean;
  /** `-1` for the copies of a multi-day event, so it takes one tab stop. */
  tabIndex?: number;
  children?: React.ReactNode;
  className?: string;
};

export function EventItem(props: EventItemProps) {
  const {
    event,
    view,
    isDragging,
    onClick,
    showTime,
    currentTime,
    isFirstDay = true,
    isLastDay = true,
    tabIndex,
    children,
    className,
    dndListeners,
  } = props;
  const start = startOf(event, currentTime);
  const end = shiftedEndOf(event, currentTime);
  const isShortEvent = differenceInMinutes(end, start) < SHORT_EVENT_MINUTES;
  const sharedProps = {
    event,
    start,
    end,
    isFirstDay,
    isLastDay,
    isDragging,
    tabIndex,
    onClick,
    dndListeners,
  };

  if (view === 'agenda') {
    return (
      <EventListRow
        event={event}
        day={start}
        onClick={onClick}
        className={className}
      />
    );
  }

  if (view === 'month') {
    const isSpan = isMultiDayEvent(event);
    let shape: EventShape = 'dot';
    if (isSpan) {
      shape = 'block';
    }
    let label = (
      <MonthDotLabel event={event} start={start} showTime={showTime} />
    );
    if (isSpan) {
      label = <MonthBarLabel event={event} start={start} showTime={showTime} />;
    }

    return (
      <EventWrapper
        {...sharedProps}
        shape={shape}
        className={cn(
          'mt-(--event-gap) h-(--event-height) items-center text-[11px] @3xl:text-xs',
          className
        )}
      >
        {children ?? label}
      </EventWrapper>
    );
  }

  return (
    <EventWrapper
      {...sharedProps}
      shape='block'
      className={cn(
        'py-1 text-[11px] @3xl:text-xs',
        isShortEvent && 'items-center',
        !isShortEvent && 'flex-col',
        className
      )}
    >
      {isShortEvent && (
        <span className='truncate'>
          {event.title}{' '}
          {showTime && (
            <span className='font-normal tabular-nums opacity-75'>
              {clockLabelOf(start)}
            </span>
          )}
        </span>
      )}
      {!isShortEvent && (
        <>
          <span className='truncate'>{event.title}</span>
          {showTime && (
            <span className='truncate font-normal tabular-nums opacity-75'>
              {eventTimeLabelOf(event, start, end)}
            </span>
          )}
        </>
      )}
    </EventWrapper>
  );
}

