      role='region'
      aria-label={label}
      tabIndex={0}
      className={cn(
        'max-h-(--calendar-scroll-height) min-h-0 flex-1 overflow-auto outline-none',
        'focus-visible:ring-ring/25 rounded-b-xl focus-visible:ring-[3px] focus-visible:ring-inset',
