'use client';

import { endOfWeek, isSameDay, isWithinInterval, startOfWeek } from 'date-fns';
import { useSyncExternalStore } from 'react';

import { EndHour, StartHour } from './constants';

const MINUTE_MS = 60_000;

function subscribeToMinutes(onMinute: () => void) {
  const timer = window.setInterval(onMinute, MINUTE_MS);
  return () => window.clearInterval(timer);
}

function currentMinute() {
  const now = Date.now();
  return Math.floor(now / MINUTE_MS) * MINUTE_MS;
}

function noMinuteOnServer() {
  return null;
}

function isNowInView(now: Date, currentDate: Date, view: 'day' | 'week') {
  if (view === 'day') {
    return isSameDay(now, currentDate);
  }
  const weekStart = startOfWeek(currentDate, { weekStartsOn: 0 });
  const weekEnd = endOfWeek(currentDate, { weekStartsOn: 0 });
  return isWithinInterval(now, { start: weekStart, end: weekEnd });
}

/** Where the current time sits on the hour grid, as a percentage, refreshed every minute. */
export function useCurrentTimeIndicator(
  currentDate: Date,
  view: 'day' | 'week'
) {
  const minute = useSyncExternalStore(
    subscribeToMinutes,
    currentMinute,
    noMinuteOnServer
  );

  if (minute === null) {
    return { currentTimePosition: 0, currentTimeVisible: false };
  }

  const now = new Date(minute);
  const minutesSinceStart =
    (now.getHours() - StartHour) * 60 + now.getMinutes();
  const minutesInView = (EndHour - StartHour) * 60;
  const currentTimePosition = (minutesSinceStart / minutesInView) * 100;
  const currentTimeVisible = isNowInView(now, currentDate, view);

  return { currentTimePosition, currentTimeVisible };
}

'use client';

import { addHours, format } from 'date-fns';
import { useState } from 'react';
import { toast } from 'sonner';

import type { CalendarEvent } from './types';
import { clockLabelOf, snapToQuarterHour } from './utils';

type EditorDialog = {
  isOpen: boolean;
  event: CalendarEvent | null;
  session: number;
};

const IDLE_DIALOG: EditorDialog = { isOpen: false, event: null, session: 0 };

export type EventEditorOptions = {
  events: CalendarEvent[];
  onEventAdd?: (event: CalendarEvent) => void;
  onEventUpdate?: (event: CalendarEvent) => void;
  onEventDelete?: (eventId: string) => void;
};

export type EventEditor = {
  /** Spread on `EventDialog`. */
  dialogProps: {
    event: CalendarEvent | null;
    isOpen: boolean;
    session: number;
    onClose: () => void;
    onSave: (event: CalendarEvent) => void;
    onDelete: (eventId: string) => void;
  };
  openEvent: (event: CalendarEvent) => void;
  openNewEvent: (startTime: Date) => void;
  moveEvent: (event: CalendarEvent) => void;
};

type UndoAction = {
  label: string;
  onClick: () => void;
};

function newEventId() {
  return Math.random().toString(36).substring(2, 11);
}

function draftAt(startTime: Date): CalendarEvent {
  const start = snapToQuarterHour(startTime);
  const end = addHours(start, 1);
  return { id: '', title: '', start, end, allDay: false };
}

function whenOf(event: CalendarEvent) {
  const start = new Date(event.start);
  const day = format(start, 'EEE, MMM d');
  if (event.allDay) {
    return day;
  }
  return `${day}, ${clockLabelOf(start)}`;
}

function notify(message: string, event: CalendarEvent, undo?: () => void) {
  let action: UndoAction | undefined;
  if (undo) {
    action = { label: 'Undo', onClick: undo };
  }
  toast(message, {
    description: whenOf(event),
    action,
    position: 'bottom-left',
  });
}

/**
 * The state behind the event dialog: which event is open, and what saving, deleting and
 * moving do, each confirmed by a toast. Deleting and moving can be undone from the toast.
 */
export function useEventEditor({
  events,
  onEventAdd,
  onEventUpdate,
  onEventDelete,
}: EventEditorOptions): EventEditor {
  const [dialog, setDialog] = useState<EditorDialog>(IDLE_DIALOG);

  function open(event: CalendarEvent | null) {
    setDialog((current) => ({
      isOpen: true,
      event,
      session: current.session + 1,
    }));
  }

  function close() {
    setDialog((current) => ({ ...current, isOpen: false }));
  }

  function openEvent(event: CalendarEvent) {
    open(event);
  }

  function openNewEvent(startTime: Date) {
    open(draftAt(startTime));
  }

  function save(event: CalendarEvent) {
    if (event.id) {
      onEventUpdate?.(event);
      notify(`Saved "${event.title}"`, event);
    } else {
      onEventAdd?.({ ...event, id: newEventId() });
      notify(`Added "${event.title}"`, event);
    }
    close();
  }

  function remove(eventId: string) {
    const deletedEvent = events.find((event) => event.id === eventId);
    onEventDelete?.(eventId);
    close();
    if (!deletedEvent) {
      return;
    }
    let undo: (() => void) | undefined;
    if (onEventAdd) {
      undo = () => onEventAdd(deletedEvent);
    }
    notify(`Deleted "${deletedEvent.title}"`, deletedEvent, undo);
  }

  function moveEvent(movedEvent: CalendarEvent) {
    const originalEvent = events.find((event) => event.id === movedEvent.id);
    onEventUpdate?.(movedEvent);
    let undo: (() => void) | undefined;
    if (originalEvent && onEventUpdate) {
      undo = () => onEventUpdate(originalEvent);
    }
    notify(`Moved "${movedEvent.title}"`, movedEvent, undo);
  }

  return {
    dialogProps: {
      event: dialog.event,
      isOpen: dialog.isOpen,
      session: dialog.session,
      onClose: close,
      onSave: save,
      onDelete: remove,
    },
    openEvent,
    openNewEvent,
    moveEvent,
  };
}

'use client';

import { useState } from 'react';

import type { CalendarEvent } from './types';

/** Events kept in local state, with the three handlers the calendar calls. */
export function useEventList(initialEvents: () => CalendarEvent[]) {
  const [events, setEvents] = useState(initialEvents);

  function addEvent(event: CalendarEvent) {
    setEvents((current) => [...current, event]);
  }

  function updateEvent(updatedEvent: CalendarEvent) {
    setEvents((current) =>
      current.map((event) => {
        if (event.id === updatedEvent.id) {
          return updatedEvent;
        }
        return event;
      })
    );
  }

  function deleteEvent(eventId: string) {
    setEvents((current) => current.filter((event) => event.id !== eventId));
  }

  return { events, addEvent, updateEvent, deleteEvent };
}

'use client';

import { useCallback, useLayoutEffect, useRef, useState } from 'react';

type EventVisibilityOptions = {
  eventHeight: number;
  eventGap: number;
};

/**
 * Measures one month cell so every cell shows as many events as fit, keeping a row for
 * the "more" button when some are left out.
 */
export function useEventVisibility({
  eventHeight,
  eventGap,
}: EventVisibilityOptions) {
  const contentRef = useRef<HTMLDivElement>(null);
  const [contentHeight, setContentHeight] = useState<number | null>(null);

  useLayoutEffect(() => {
    const content = contentRef.current;
    if (!content) {
      return;
    }
    const observer = new ResizeObserver(() => {
      setContentHeight(content.clientHeight);
    });
    observer.observe(content);
    return () => observer.disconnect();
  }, []);

  const getVisibleEventCount = useCallback(
    (totalEvents: number) => {
      if (!contentHeight) {
        return totalEvents;
      }
      const maxEvents = Math.floor(contentHeight / (eventHeight + eventGap));
      if (totalEvents <= maxEvents) {
        return totalEvents;
      }
      return Math.max(0, maxEvents - 1);
    },
    [contentHeight, eventHeight, eventGap]
  );

  return { contentRef, contentHeight, getVisibleEventCount };
}

'use client';

import {
  addDays,
  addMonths,
  endOfWeek,
  isAfter,
  isBefore,
  isSameDay,
  startOfDay,
  startOfWeek,
} from 'date-fns';
import { useLayoutEffect, useRef, useState } from 'react';

import { WeekStartsOn } from './constants';
import { dayKeyOf } from './navigation';

type RovingDayOptions = {
  /** The day that holds the tab stop until one is picked. */
  defaultDay: Date;
  firstDay: Date;
  lastDay: Date;
};

function movedDayOf(day: Date, key: string) {
  if (key === 'ArrowLeft') {
    return addDays(day, -1);
  }
  if (key === 'ArrowRight') {
    return addDays(day, 1);
  }
  if (key === 'ArrowUp') {
    return addDays(day, -7);
  }
  if (key === 'ArrowDown') {
    return addDays(day, 7);
  }
  if (key === 'Home') {
    return startOfWeek(day, { weekStartsOn: WeekStartsOn });
  }
  if (key === 'End') {
    const weekEnd = endOfWeek(day, { weekStartsOn: WeekStartsOn });
    return startOfDay(weekEnd);
  }
  if (key === 'PageUp') {
    return addMonths(day, -1);
  }
  if (key === 'PageDown') {
    return addMonths(day, 1);
  }
  return null;
}

function clampedDayOf(day: Date, firstDay: Date, lastDay: Date) {
  if (isBefore(day, firstDay)) {
    return firstDay;
  }
  if (isAfter(day, lastDay)) {
    return lastDay;
  }
  return day;
}

function isWithinRange(day: Date, firstDay: Date, lastDay: Date) {
  const isBeforeRange = isBefore(day, firstDay);
  const isAfterRange = isAfter(day, lastDay);
  return !isBeforeRange && !isAfterRange;
}

function activeDayOf(
  storedDay: Date | null,
  { defaultDay, firstDay, lastDay }: RovingDayOptions
) {
  if (!storedDay) {
    return clampedDayOf(defaultDay, firstDay, lastDay);
  }
  if (!isWithinRange(storedDay, firstDay, lastDay)) {
    return clampedDayOf(defaultDay, firstDay, lastDay);
  }
  return storedDay;
}

function isDayButton(target: EventTarget) {
  if (!(target instanceof HTMLElement)) {
    return false;
  }
  return target.dataset.day !== undefined;
}

/**
 * One tab stop for a grid of days: the arrow keys move by day and week, Home and End go to
 * the ends of the week, Page Up and Page Down move by month, and focus follows.
 */
export function useRovingDay(options: RovingDayOptions) {
  const gridRef = useRef<HTMLDivElement>(null);
  const shouldFocusRef = useRef(false);
  const [storedDay, setStoredDay] = useState<Date | null>(null);
  const activeDay = activeDayOf(storedDay, options);
  const activeKey = dayKeyOf(activeDay);

  useLayoutEffect(() => {
    if (!shouldFocusRef.current) {
      return;
    }
    shouldFocusRef.current = false;
    const selector = `[data-day="${activeKey}"]`;
    const target = gridRef.current?.querySelector<HTMLElement>(selector);
    target?.focus();
  }, [activeKey]);

  function handleKeyDown(keyEvent: React.KeyboardEvent) {
    if (!isDayButton(keyEvent.target)) {
      return;
    }
    const movedDay = movedDayOf(activeDay, keyEvent.key);
    if (!movedDay) {
      return;
    }
    keyEvent.preventDefault();
    const nextDay = clampedDayOf(movedDay, options.firstDay, options.lastDay);
    if (isSameDay(nextDay, activeDay)) {
      return;
    }
    shouldFocusRef.current = true;
    setStoredDay(nextDay);
  }

  function tabIndexOf(day: Date) {
    if (isSameDay(day, activeDay)) {
      return 0;
    }
    return -1;
  }

  return {
    gridRef,
    activeDay,
    handleKeyDown,
    tabIndexOf,
    rememberDay: setStoredDay,
  };
}

import {
  addHours,
  areIntervalsOverlapping,
  differenceInMinutes,
  eachDayOfInterval,
  format,
  getHours,
  getMinutes,
  isAfter,
  isSameDay,
  isToday,
  startOfDay,
} from 'date-fns';

import {
  DefaultEventColor,
  DefaultStartHour,
  StartHour,
  WeekCellsHeight,
} from './constants';
import { dayKeyOf } from './navigation';
import type { CalendarEvent, EventColor } from './types';

const LAST_START_HOUR = 23;

/** A clock time as `9am` or `9:30am`, short enough for a month cell. */
export function clockLabelOf(date: Date) {
  let pattern = 'h:mma';
  if (getMinutes(date) === 0) {
    pattern = 'ha';
  }
  return format(date, pattern).toLowerCase();
}

export function timeRangeLabelOf(start: Date, end: Date) {
  const startLabel = clockLabelOf(start);
  const endLabel = clockLabelOf(end);
  return `${startLabel} – ${endLabel}`;
}

/** When the event runs on this day: its hours, its start, its end, or the whole day. */
export function timeLabelOnDay(event: CalendarEvent, day: Date) {
  const start = new Date(event.start);
  const end = new Date(event.end);
  const startsThatDay = isSameDay(day, start);
  const endsThatDay = isSameDay(day, end);
  const isWithinDay = startsThatDay && endsThatDay;

  if (event.allDay) {
    return 'All day';
  }
  if (isWithinDay) {
    return timeRangeLabelOf(start, end);
  }
  if (startsThatDay) {
    return `From ${clockLabelOf(start)}`;
  }
  if (endsThatDay) {
    return `Until ${clockLabelOf(end)}`;
  }
  return 'All day';
}

export function ariaCurrentDateOf(isCurrentDay: boolean) {
  if (isCurrentDay) {
    return 'date' as const;
  }
  return undefined;
}

export function eventCountLabelOf(count: number) {
  if (count === 0) {
    return 'No events';
  }
  if (count === 1) {
    return '1 event';
  }
  return `${count} events`;
}

/** How many events touch each day, keyed by `yyyy-MM-dd`. */
export function eventDayCountsOf(events: CalendarEvent[]) {
  const counts = new Map<string, number>();
  for (const event of events) {
    const firstDay = startOfDay(new Date(event.start));
    const lastDay = startOfDay(new Date(event.end));
    if (isAfter(firstDay, lastDay)) {
      continue;
    }
    const days = eachDayOfInterval({ start: firstDay, end: lastDay });
    for (const day of days) {
      const key = dayKeyOf(day);
      const current = counts.get(key) ?? 0;
      counts.set(key, current + 1);
    }
  }
  return counts;
}

function nextFullHourOf(time: Date) {
  const nextHour = getHours(time) + 1;
  return Math.min(nextHour, LAST_START_HOUR);
}

/** Where a new event starts on a day: the next full hour today, the morning on any other day. */
export function defaultStartOf(day: Date) {
  const start = startOfDay(day);
  let hour = DefaultStartHour;
  if (isToday(day)) {
    hour = nextFullHourOf(new Date());
  }
  start.setHours(hour);
  return start;
}

export function snapToQuarterHour(time: Date) {
  const snapped = new Date(time);
  const minutes = snapped.getMinutes();
  const remainder = minutes % 15;
  if (remainder === 0) {
    return snapped;
  }
  const isCloserToPrevious = remainder < 7.5;
  if (isCloserToPrevious) {
    snapped.setMinutes(minutes - remainder, 0, 0);
    return snapped;
  }
  snapped.setMinutes(minutes + 15 - remainder, 0, 0);
  return snapped;
}

export type PositionedEvent = {
  event: CalendarEvent;
  top: number;
  height: number;
  left: number;
  width: number;
  zIndex: number;
};

/** The `--chip` colour of an event block, always a theme token. */
export function eventChipStyle(color?: EventColor) {
  const token = color ?? DefaultEventColor;
  return { '--chip': `var(--${token})` } as React.CSSProperties;
}

export function getBorderRadiusClasses(
  isFirstDay: boolean,
  isLastDay: boolean
) {
  const isSingleDay = isFirstDay && isLastDay;
  if (isSingleDay) {
    return 'rounded-sm';
  }
  if (isFirstDay) {
    return 'rounded-s-sm rounded-e-none';
  }
  if (isLastDay) {
    return 'rounded-e-sm rounded-s-none';
  }
  return 'rounded-none';
}

export function isMultiDayEvent(event: CalendarEvent) {
  const eventStart = new Date(event.start);
  const eventEnd = new Date(event.end);
  const isSpanningDays = !isSameDay(eventStart, eventEnd);
  return Boolean(event.allDay) || isSpanningDays;
}

/** Whether the event starts, ends or runs through this day. */
export function occursOnDay(event: CalendarEvent, day: Date) {
  const eventStart = new Date(event.start);
  const eventEnd = new Date(event.end);
  const startsThatDay = isSameDay(day, eventStart);
  const endsThatDay = isSameDay(day, eventEnd);
  const runsThroughDay = day > eventStart && day < eventEnd;
  return startsThatDay || endsThatDay || runsThroughDay;
}

function byStart(a: CalendarEvent, b: CalendarEvent) {
  return new Date(a.start).getTime() - new Date(b.start).getTime();
}

export function getEventsForDay(events: CalendarEvent[], day: Date) {
  const startingThatDay = events.filter((event) =>
    isSameDay(day, new Date(event.start))
  );
  return startingThatDay.sort(byStart);
}

/** Multi-day events first, then by start time. */
export function sortEvents(events: CalendarEvent[]) {
  return [...events].sort((a, b) => {
    const aIsMultiDay = isMultiDayEvent(a);
    const bIsMultiDay = isMultiDayEvent(b);
    if (aIsMultiDay === bIsMultiDay) {
      return byStart(a, b);
    }
    if (aIsMultiDay) {
      return -1;
    }
    return 1;
  });
}

/** Multi-day events that cover this day without starting on it. */
export function getSpanningEventsForDay(events: CalendarEvent[], day: Date) {
  return events.filter((event) => {
    if (!isMultiDayEvent(event)) {
      return false;
    }
    const startsThatDay = isSameDay(day, new Date(event.start));
    if (startsThatDay) {
      return false;
    }
    return occursOnDay(event, day);
  });
}

export function getAllEventsForDay(events: CalendarEvent[], day: Date) {
  return events.filter((event) => occursOnDay(event, day));
}

export function getAgendaEventsForDay(events: CalendarEvent[], day: Date) {
  return getAllEventsForDay(events, day).sort(byStart);
}

function byStartThenLongest(a: CalendarEvent, b: CalendarEvent) {
  const startDifference = byStart(a, b);
  if (startDifference !== 0) {
    return startDifference;
  }
  const aDuration = differenceInMinutes(new Date(a.end), new Date(a.start));
  const bDuration = differenceInMinutes(new Date(b.end), new Date(b.start));
  return bDuration - aDuration;
}

function hourOf(date: Date) {
  return getHours(date) + getMinutes(date) / 60;
}

type PlacedInterval = { start: Date; end: Date };

function firstFreeColumn(
  columns: PlacedInterval[][],
  interval: PlacedInterval
) {
  let columnIndex = 0;
  while (columnIndex < columns.length) {
    const column = columns[columnIndex];
    const overlaps = column.some((placed) =>
      areIntervalsOverlapping(interval, placed)
    );
    if (!overlaps) {
      return columnIndex;
    }
    columnIndex++;
  }
  return columnIndex;
}

function widthOfColumn(columnIndex: number) {
  if (columnIndex === 0) {
    return 1;
  }
  return 0.9;
}

/**
 * Places the timed events of one day on the hour grid. Overlapping events move to the next
 * column, indented by 10% and drawn above the previous one.
 */
export function positionTimedEvents(events: CalendarEvent[], day: Date) {
  const dayStart = startOfDay(day);
  const dayEnd = addHours(dayStart, 24);
  const columns: PlacedInterval[][] = [];
  const sortedEvents = [...events].sort(byStartThenLongest);

  return sortedEvents.map((event): PositionedEvent => {
    const eventStart = new Date(event.start);
    const eventEnd = new Date(event.end);
    let visibleStart = dayStart;
    if (isSameDay(day, eventStart)) {
      visibleStart = eventStart;
    }
    let visibleEnd = dayEnd;
    if (isSameDay(day, eventEnd)) {
      visibleEnd = eventEnd;
    }
    const startHour = hourOf(visibleStart);
    const endHour = hourOf(visibleEnd);
    const columnIndex = firstFreeColumn(columns, {
      start: visibleStart,
      end: visibleEnd,
    });
    if (!columns[columnIndex]) {
      columns[columnIndex] = [];
    }
    columns[columnIndex].push({ start: eventStart, end: eventEnd });

    return {
      event,
      top: (startHour - StartHour) * WeekCellsHeight,
      height: (endHour - startHour) * WeekCellsHeight,
      left: columnIndex * 0.1,
      width: widthOfColumn(columnIndex),
      zIndex: 10 + columnIndex,
    };
  });
}

'use client';

import { cn } from '@/registry/ndeko/lib/utils';
import { Tabs, TabsList, TabsTab } from '@/registry/ndeko/ui/tabs';

import { ViewOptions } from './constants';
import type { CalendarView } from './types';

type ViewSwitcherProps = {
  views: CalendarView[];
  value: CalendarView;
  onValueChange: (view: CalendarView) => void;
  className?: string;
};

function isCalendarView(value: unknown): value is CalendarView {
  return ViewOptions.some((option) => option.view === value);
}

/**
 * A segmented control whose thumb travels to the chosen view. It takes a row of its own on
 * a narrow calendar and sits in the header row on a wide one.
 */
export function ViewSwitcher({
  views,
  value,
  onValueChange,
  className,
}: ViewSwitcherProps) {
  const options = ViewOptions.filter((option) => views.includes(option.view));

  function changeView(nextView: unknown) {
    if (isCalendarView(nextView)) {
      onValueChange(nextView);
    }
  }

  return (
    <Tabs
      value={value}
      onValueChange={changeView}
      className={cn('order-last w-full @2xl:order-none @2xl:w-auto', className)}
    >
      <TabsList
        variant='segmented'
        aria-label='Calendar view'
        className='w-full @2xl:w-fit'
      >
        {options.map((option) => (
          <TabsTab
            key={option.view}
            value={option.view}
            aria-keyshortcuts={option.shortcut}
            className='flex-1 px-2 @2xl:flex-none @2xl:px-3'
          >
            {option.label}
          </TabsTab>
        ))}
      </TabsList>
    </Tabs>
  );
}

'use client';

import {
  eachDayOfInterval,
  endOfWeek,
  format,
  isBefore,
  isSameDay,
  isToday,
  startOfWeek,
} from 'date-fns';
import { useMemo } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';

import { WeekStartsOn } from './constants';
import { EventItem } from './event-item';
import {
  CurrentTimeLine,
  HourLabels,
  hoursOfDay,
  PositionedEvents,
  QuarterSlots,
  TimeGridScroller,
} from './time-grid';
import type { CalendarEvent } from './types';
import { useCurrentTimeIndicator } from './use-current-time-indicator';
import {
  ariaCurrentDateOf,
  isMultiDayEvent,
  occursOnDay,
  positionTimedEvents,
} from './utils';

/** An hour gutter, then seven days that keep a readable width by scrolling sideways on a phone. */
const WEEK_COLUMNS = 'grid grid-cols-[3.5rem_repeat(7,minmax(0,1fr))]';

const STICKY_GUTTER = 'bg-card sticky left-0 z-20';

const DAY_NUMBER =
  'inline-flex size-6 items-center justify-center rounded-full text-[13px] tabular-nums group-data-today/day:bg-primary group-data-today/day:font-medium group-data-today/day:text-primary-foreground';

type WeekViewProps = {
  currentDate: Date;
  events: CalendarEvent[];
  onEventSelect: (event: CalendarEvent) => void;
  onEventCreate: (startTime: Date) => void;
  /** Opens a day from its heading. Without it the headings are plain text. */
  onDaySelect?: (day: Date) => void;
};

function isTimedEvent(event: CalendarEvent) {
  return !isMultiDayEvent(event);
}

function DayHeadingContent({ day }: { day: Date }) {
  return (
    <>
      <span className='text-muted-foreground text-xs'>
        {format(day, 'EEE')}
      </span>
      <span className={DAY_NUMBER}>{format(day, 'd')}</span>
    </>
  );
}

type DayHeadingProps = {
  day: Date;
  onDaySelect?: (day: Date) => void;
};

function DayHeading({ day, onDaySelect }: DayHeadingProps) {
  const isTodayColumn = isToday(day);

  if (!onDaySelect) {
    return (
      <div
        className='group/day flex items-center justify-center gap-1.5 py-2'
        data-today={isTodayColumn || undefined}
      >
        <DayHeadingContent day={day} />
      </div>
    );
  }

  return (
    <div className='flex justify-center py-1.5'>
      <button
        type='button'
        className='group/day hover:bg-foreground/5 focus-visible:ring-ring/25 flex cursor-pointer items-center gap-1.5 rounded-md px-1.5 py-0.5 transition-colors duration-150 outline-none focus-visible:ring-[3px]'
        data-today={isTodayColumn || undefined}
        aria-label={format(day, 'EEEE, MMMM d')}
        aria-current={ariaCurrentDateOf(isTodayColumn)}
        onClick={() => onDaySelect(day)}
      >
        <DayHeadingContent day={day} />
      </button>
    </div>
  );
}

type AllDayCellProps = {
  day: Date;
  isFirstColumn: boolean;
  weekStart: Date;
  events: CalendarEvent[];
  onEventClick: (event: CalendarEvent, clickEvent: React.MouseEvent) => void;
};

function AllDayCell({
  day,
  isFirstColumn,
  weekStart,
  events,
  onEventClick,
}: AllDayCellProps) {
  const dayEvents = events.filter((event) => occursOnDay(event, day));

  return (
    <div className='hairline-r border-border relative p-1 last:border-r-0'>
      {dayEvents.map((event) => {
        const eventStart = new Date(event.start);
        const isFirstDay = isSameDay(day, eventStart);
        const isLastDay = isSameDay(day, new Date(event.end));
        const startsBeforeWeek = isBefore(eventStart, weekStart);
        const isFirstVisibleDay = isFirstColumn && startsBeforeWeek;
        const shouldShowTitle = isFirstDay || isFirstVisibleDay;
        let tabIndex: number | undefined;
        if (!shouldShowTitle) {
          tabIndex = -1;
        }

        return (
          <EventItem
            key={`spanning-${event.id}`}
            onClick={(clickEvent) => onEventClick(event, clickEvent)}
            event={event}
            view='month'
            tabIndex={tabIndex}
            isFirstDay={isFirstDay}
            isLastDay={isLastDay}
          >
            <span
              className={cn('truncate', !shouldShowTitle && 'invisible')}
              aria-hidden='true'
            >
              {event.title}
            </span>
          </EventItem>
        );
      })}
    </div>
  );
}

export function WeekView({
  currentDate,
  events,
  onEventSelect,
  onEventCreate,
  onDaySelect,
}: WeekViewProps) {
  const weekStart = useMemo(
    () => startOfWeek(currentDate, { weekStartsOn: WeekStartsOn }),
    [currentDate]
  );
  const days = useMemo(() => {
    const weekEnd = endOfWeek(currentDate, { weekStartsOn: WeekStartsOn });
    return eachDayOfInterval({ start: weekStart, end: weekEnd });
  }, [currentDate, weekStart]);
  const hours = useMemo(() => hoursOfDay(currentDate), [currentDate]);

  const allDayEvents = useMemo(() => {
    const multiDayEvents = events.filter(isMultiDayEvent);
    return multiDayEvents.filter((event) =>
      days.some((day) => occursOnDay(event, day))
    );
  }, [events, days]);

  const positionedDayEvents = useMemo(() => {
    const timedEvents = events.filter(isTimedEvent);
    return days.map((day) => {
      const dayEvents = timedEvents.filter((event) => occursOnDay(event, day));
      return positionTimedEvents(dayEvents, day);
    });
  }, [days, events]);

  const { currentTimePosition, currentTimeVisible } = useCurrentTimeIndicator(
    currentDate,
    'week'
  );
  const showAllDaySection = allDayEvents.length > 0;
  const gridLabel = `Week of ${format(weekStart, 'MMMM d')}`;

  function handleEventClick(
    event: CalendarEvent,
    clickEvent: React.MouseEvent
  ) {
    clickEvent.stopPropagation();
    onEventSelect(event);
  }

  return (
    <div data-slot='week-view' className='flex min-h-0 flex-1 flex-col'>
      <TimeGridScroller label={gridLabel}>
        <div className='min-w-[42rem] @3xl:min-w-0'>
          <div className='bg-card hairline-b border-border sticky top-0 z-30'>
            <div className={WEEK_COLUMNS}>
              <div className={STICKY_GUTTER} />
              {days.map((day) => (
                <DayHeading
                  key={day.toString()}
                  day={day}
                  onDaySelect={onDaySelect}
                />
              ))}
            </div>
            {showAllDaySection && (
              <div className={cn(WEEK_COLUMNS, 'hairline-t border-border')}>
                <div
                  className={cn(
                    STICKY_GUTTER,
                    'hairline-r border-border text-muted-foreground flex items-end justify-end pe-2 pb-2 text-[10px] @3xl:text-xs'
                  )}
                >
                  All day
                </div>
                {days.map((day, dayIndex) => (
                  <AllDayCell
                    key={day.toString()}
                    day={day}
                    isFirstColumn={dayIndex === 0}
                    weekStart={weekStart}
                    events={allDayEvents}
                    onEventClick={handleEventClick}
                  />
                ))}
              </div>
            )}
          </div>

          <div className={WEEK_COLUMNS}>
            <div className={cn(STICKY_GUTTER, 'hairline-r border-border')}>
              <HourLabels hours={hours} />
            </div>

            {days.map((day, dayIndex) => {
              const isTodayColumn = isToday(day);
              const showsCurrentTime = currentTimeVisible && isTodayColumn;

              return (
                <div
                  key={day.toString()}
                  className='hairline-r border-border data-today:bg-primary/[0.025] relative last:border-r-0'
                  data-today={isTodayColumn || undefined}
                >
                  <PositionedEvents
                    positionedEvents={positionedDayEvents[dayIndex] ?? []}
                    view='week'
                    onEventClick={handleEventClick}
                  />
                  {showsCurrentTime && (
                    <CurrentTimeLine position={currentTimePosition} />
                  )}
                  <QuarterSlots
                    day={day}
                    hours={hours}
                    idPrefix='week-cell'
                    onEventCreate={onEventCreate}
                  />
                </div>
              );
            })}
          </div>
        </div>
      </TimeGridScroller>
    </div>
  );
}

'use client';

import {
  addDays,
  eachDayOfInterval,
  eachMonthOfInterval,
  endOfMonth,
  endOfYear,
  format,
  getDay,
  isSameDay,
  isToday,
  startOfDay,
  startOfYear,
} from 'date-fns';
import { useMemo } from 'react';

import { cn } from '@/registry/ndeko/lib/utils';

import { WeekStartsOn } from './constants';
import { dayKeyOf } from './navigation';
import type { CalendarEvent } from './types';
import { useRovingDay } from './use-roving-day';
import {
  ariaCurrentDateOf,
  eventCountLabelOf,
  eventDayCountsOf,
} from './utils';

const REFERENCE_SUNDAY = new Date(2023, 0, 1);

const WEEKDAY_INITIALS = Array.from({ length: 7 }, (_, index) => {
  const weekday = addDays(REFERENCE_SUNDAY, index + WeekStartsOn);
  return { key: format(weekday, 'EEE'), initial: format(weekday, 'EEEEE') };
});

const YEAR_DAY = [
  'mx-auto flex aspect-square w-full max-w-8 cursor-pointer items-center justify-center rounded-full text-[11px] tabular-nums text-foreground outline-none @4xl:text-xs',
  'transition-[background-color,scale,box-shadow] duration-150 ease-(--ease-out-strong) active:scale-90',
  'not-data-today:hover:bg-foreground/[0.07] focus-visible:ring-[3px] focus-visible:ring-ring/25',
  'data-today:bg-primary data-today:font-medium data-today:text-primary-foreground',
  'data-selected:ring-[1.5px] data-selected:ring-primary-ink',
].join(' ');

/** Busier days take a deeper tint of the brand: one event, two, three or more. */
const DENSITY_CLASSES = [
  '',
  'bg-primary/[0.09]',
  'bg-primary/[0.18]',
  'bg-primary/[0.3]',
];

const LEGEND = [
  { label: '1 event', className: DENSITY_CLASSES[1] },
  { label: '2 events', className: DENSITY_CLASSES[2] },
  { label: '3 or more', className: DENSITY_CLASSES[3] },
  { label: 'Today', className: 'bg-primary' },
];

function densityClassOf(count: number) {
  const level = Math.min(count, DENSITY_CLASSES.length - 1);
  return DENSITY_CLASSES[level];
}

function dayLabelOf(day: Date, count: number) {
  const date = format(day, 'EEEE, MMMM d');
  if (count === 0) {
    return date;
  }
  return `${date}, ${eventCountLabelOf(count)}`;
}

function leadingBlanksOf(month: Date) {
  const weekday = getDay(month);
  return (weekday - WeekStartsOn + 7) % 7;
}

function isSelectedDay(day: Date, selectedDay: Date | null | undefined) {
  if (!selectedDay) {
    return false;
  }
  return isSameDay(day, selectedDay);
}

function ariaPressedOf(isSelectable: boolean, isSelected: boolean) {
  if (!isSelectable) {
    return undefined;
  }
  return isSelected;
}

function tabIndexOf(day: Date, activeDay: Date) {
  if (isSameDay(day, activeDay)) {
    return 0;
  }
  return -1;
}

type YearDayProps = {
  day: Date;
  count: number;
  activeDay: Date;
  selectedDay?: Date | null;
  onDaySelect: (day: Date) => void;
  onFocusDay: (day: Date) => void;
};

function YearDay({
  day,
  count,
  activeDay,
  selectedDay,
  onDaySelect,
  onFocusDay,
}: YearDayProps) {
  const isTodayDay = isToday(day);
  const isSelectable = selectedDay !== undefined;
  const isSelected = isSelectedDay(day, selectedDay);

  function selectDay() {
    onFocusDay(day);
    onDaySelect(day);
  }

  return (
    <button
      type='button'
      className={cn(YEAR_DAY, densityClassOf(count))}
      data-day={dayKeyOf(day)}
      data-today={isTodayDay || undefined}
      data-selected={isSelected || undefined}
      tabIndex={tabIndexOf(day, activeDay)}
      aria-label={dayLabelOf(day, count)}
      aria-current={ariaCurrentDateOf(isTodayDay)}
      aria-pressed={ariaPressedOf(isSelectable, isSelected)}
      onClick={selectDay}
      onFocus={() => onFocusDay(day)}
    >
      {format(day, 'd')}
    </button>
  );
}

type MonthHeadingProps = {
  month: Date;
  onMonthSelect?: (month: Date) => void;
};

function MonthHeading({ month, onMonthSelect }: MonthHeadingProps) {
  const name = format(month, 'MMMM');

  if (!onMonthSelect) {
    return <h3 className='px-1 text-[13px] font-medium'>{name}</h3>;
  }

  return (
    <h3 className='flex'>
      <button
        type='button'
        className='hover:bg-foreground/5 focus-visible:ring-ring/25 cursor-pointer rounded-md px-1 text-[13px] font-medium transition-colors duration-150 outline-none focus-visible:ring-[3px]'
        aria-label={`Open ${format(month, 'MMMM yyyy')}`}
        onClick={() => onMonthSelect(month)}
      >
        {name}
      </button>
    </h3>
  );
}

type YearMonthProps = {
  month: Date;
  counts: Map<string, number>;
  activeDay: Date;
  selectedDay?: Date | null;
  onDaySelect: (day: Date) => void;
  onFocusDay: (day: Date) => void;
  onMonthSelect?: (month: Date) => void;
};

function YearMonth({
  month,
  counts,
  activeDay,
  selectedDay,
  onDaySelect,
  onFocusDay,
  onMonthSelect,
}: YearMonthProps) {
  const days = eachDayOfInterval({ start: month, end: endOfMonth(month) });
  const blanks = Array.from(
    { length: leadingBlanksOf(month) },
    (_, index) => index
  );

  return (
    <section
      aria-label={format(month, 'MMMM yyyy')}
      className='flex min-w-0 flex-col gap-1.5'
    >
      <MonthHeading month={month} onMonthSelect={onMonthSelect} />
      <div className='grid grid-cols-7' aria-hidden='true'>
        {WEEKDAY_INITIALS.map((weekday) => (
          <span
            key={weekday.key}
            className='text-muted-foreground text-center text-[10px] @4xl:text-[11px]'
          >
            {weekday.initial}
          </span>
        ))}
      </div>
      <div className='grid grid-cols-7 gap-y-0.5'>
        {blanks.map((blank) => (
          <span key={`blank-${blank}`} aria-hidden='true' />
        ))}
        {days.map((day) => {
          const dayKey = dayKeyOf(day);
          const count = counts.get(dayKey) ?? 0;
          return (
            <YearDay
              key={dayKey}
              day={day}
              count={count}
              activeDay={activeDay}
              selectedDay={selectedDay}
              onDaySelect={onDaySelect}
              onFocusDay={onFocusDay}
            />
          );
        })}
      </div>
    </section>
  );
}

function YearLegend() {
  return (
    <div
      aria-hidden='true'
      className='text-muted-foreground flex flex-wrap items-center justify-end gap-x-4 gap-y-1 px-4 pb-4 text-xs @xl/year:px-5'
    >
      {LEGEND.map((entry) => (
        <span key={entry.label} className='flex items-center gap-1.5'>
          <span className={cn('size-3 rounded-full', entry.className)} />
          {entry.label}
        </span>
      ))}
    </div>
  );
}

type YearViewProps = {
  currentDate: Date;
  events: CalendarEvent[];
  /** Picks a day: the all-in-one calendar opens it in the day view. */
  onDaySelect: (day: Date) => void;
  /** Opens a month from its name. Without it the names are plain headings. */
  onMonthSelect?: (month: Date) => void;
  /** The picked day, ringed. Leave it out when picking a day leaves the year view. */
  selectedDay?: Date | null;
};

/** Twelve compact months. Days with events are tinted by how busy they are; today is filled. */
export function YearView({
  currentDate,
  events,
  onDaySelect,
  onMonthSelect,
  selectedDay,
}: YearViewProps) {
  const yearStart = startOfYear(currentDate);
  const yearEnd = startOfDay(endOfYear(currentDate));
  const months = eachMonthOfInterval({ start: yearStart, end: yearEnd });
  const counts = useMemo(() => eventDayCountsOf(events), [events]);
  const { gridRef, activeDay, handleKeyDown, rememberDay } = useRovingDay({
    defaultDay: currentDate,
    firstDay: yearStart,
    lastDay: yearEnd,
  });

  return (
    <div
      data-slot='year-view'
      className='@container/year min-h-0 flex-1 overflow-y-auto'
    >
      <div
        ref={gridRef}
        onKeyDown={handleKeyDown}
        className='grid grid-cols-2 gap-x-5 gap-y-5 p-4 @xl/year:grid-cols-3 @xl/year:gap-x-8 @xl/year:p-5 @4xl/year:grid-cols-4'
      >
        {months.map((month) => (
          <YearMonth
            key={format(month, 'yyyy-MM')}
            month={month}
            counts={counts}
            activeDay={activeDay}
            selectedDay={selectedDay}
            onDaySelect={onDaySelect}
            onFocusDay={rememberDay}
            onMonthSelect={onMonthSelect}
          />
        ))}
      </div>
      <YearLegend />
    </div>
  );
}
